export const getKeywordDefinition = (word, fallbackTopic = "Java Technical Concept", fallbackQuestion = "") => {
  if (!word) return null;

  // Exact match
  if (JAVA_KEYWORD_DEFINITIONS[word]) {
    return JAVA_KEYWORD_DEFINITIONS[word];
  }

  // Case-insensitive match
  const lowerWord = word.toLowerCase().trim();
  const matchedKey = Object.keys(JAVA_KEYWORD_DEFINITIONS).find(
    k => k.toLowerCase().trim() === lowerWord
  );

  if (matchedKey && JAVA_KEYWORD_DEFINITIONS[matchedKey]) {
    return JAVA_KEYWORD_DEFINITIONS[matchedKey];
  }

  // Default fallback
  return {
    word: word,
    topic: fallbackTopic,
    definition: `${word} is a key concept in ${fallbackTopic}.`,
    contextQuestion: fallbackQuestion
  };
};
